E       assert 1 == (1 + 5)
E        +  where 1 = len({'811ecec8b6159596d56c3a9b432c8b779d6dc14e31a5c91b1399716a1b136696'})
E        +  and   5 = len([{'model': 'nram-qwen3-14b-awq', 'messages': [{'role': 'user', 'content': 'prompt B'}], 'max_tokens': 1, 'temperature'...'nram-qwen3-14b-awq', 'messages': [{'role': 'user', 'content': 'prompt A'}], 'max_tokens': 1, 'temperature': 0.0, ...}])

